    /**
     * Путь символа: обычно сетка 960×960 со сдвигом по y (в SVG viewBox 0 -960 960 960),
     * у части старых символов — сетка 24×24 без сдвига.
     */
    private fun symbol(name: String, path: String, grid: Float = 960f, mirrored: Boolean = false): ImageVector =
        ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = grid, viewportHeight = grid)
            .addGroup(
                scaleX = if (mirrored) -1f else 1f,
                pivotX = grid / 2,
                pivotY = if (grid == 960f) -480f else grid / 2,
                translationY = if (grid == 960f) 960f else 0f,
            )
            .addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
            .clearGroup()
            .build()
}
